    reserveAta: TAccountMetas[3];
    usdcMint: TAccountMetas[4];
    /** Keeper's USDC, holding the proceeds of the swap. */
    usdcFrom: TAccountMetas[5];
    /** Borrower's USDC. Only required when the payout mode is `Payout`. */
